public static void main(Args _args)
{
    SalesId salesId= "013576";
    SalesTable salesTable = SalesTable::find(salesId);
    SalesFormLetter salesFormLetter;
    container salesLineReferences;
    List SAPItemsQtys = new List(Types::String);
    ARGSalesOrderInvoiceCreateLineClass auxSalesOrderInvoiceLineClass;
    ARGSalesOrderInvoiceCreateResponse invoiceResponse;

    Set seSAPItems = new Set(Types::String);

    List lines = new List(Types::String);
    ListIterator   literator;
    str salesInvoiceLine;
    int i;
    SalesLine salesLine;

    SalesParmLine               salesParmLine;
    FormletterOutputContract    outputContract;
    WMSPickingRoute             wmsPickingRoute;
    //ListIterator                literator;
