    Set                         missingItems;
    SetEnumerator               se;
    str sapItemsData;
    int res = 0;
    str                         item;

    //Create lines
    //lines = _request.parmsalesOrderInvoiceCreateLineClassArray();
    lines.addEnd("0162");
    lines.addEnd("0163");
    //lines.addEnd("0164");

    Info("Empieza");
    if (lines)
    {
        literator = new ListIterator(lines);
        while (literator.more())
        {
            salesInvoiceLine = literator.value();

            select salesLine
                        where salesLine.SalesId == salesId
                        join salesTable
                where salesTable.SalesId == salesLine.SalesId && salesLine.ItemId == salesInvoiceLine;

            seSAPItems.add(salesLine.InventTransId);

            SAPItemsQtys.addEnd(salesLine.ItemId);
            SAPItemsQtys.addEnd(int2Str(5));

            literator.next();
        }
    }

    ttsbegin;
    salesFormLetter = SalesFormLetter::construct(DocumentStatus::Confirmation);
    salesFormLetter.update(salesTable, systemDateGet(), SalesUpdate::All);
    ttscommit;

    //ttsbegin;
    //salesFormLetter = SalesFormLetter::construct(DocumentStatus::PickingList);

    //salesFormLetter.salesTable(salesTable);
    //salesFormLetter.initParmSalesTable(salesFormLetter.salesTable());
