    //            sapItemsData = literator.value();

    //            if (SAPItemsData == salesParmLine.InventTransId)
    //            {
    //                //qty
    //                literator.next();
    //                sapItemsData = literator.value();

    //                //if (str2Int(sapItemsData) != real2int(salesParmLine.InventNow))
    //                //{
    //                //    res = real2int(salesParmLine.InventNow) - str2Int(sapItemsData);
    //                    salesParmLine.InventNow = str2Int(sapItemsData);
    //                    salesParmLine.update();
    //                //}
    //                break;
    //            }
    //            literator.next();
    //        }
    //    }
    //}
    //missingItems = Set::difference(seItemsHQ,seSAPItems);

    //while select forupdate salesParmLine
    //    where salesParmLine.ParmId == salesFormLetter.parmId() && salesParmLine.OrigSalesId == salesId
    //{
    //    se = missingItems.getEnumerator();
    //    while(se.moveNext())
    //    {
    //        item = se.current();
    //        if (item == salesParmLine.InventTransId)
    //        {
    //            salesParmLine.delete();
    //        }
    //    }
    //}

    //salesFormLetter.run();

    //outputContract  = salesFormLetter.getOutputContract();
    //wmsPickingRoute = outputContract.parmJournal();
    //ttscommit;

    //ttsbegin;
    //WMSPickingRouteID pickingRouteID = wmsPickingRoute.pickingRouteID;    // Route id to be picked

    //List list = new List(Types::String);

    //list.addEnd(pickingRouteID);

    //WMSPickingRoute::finishMulti(list.pack());   // Note - this is not in a single tts, so some routes might be posted and others fail

    //ttscommit;

    CustPackingSlipJour custPackingSlipJour;
    SalesFormLetter_PackingSlip     salesFormLetter_PackingSlip;      


    ttsbegin;

    literator = new ListIterator(SAPItemsQtys);
    while (literator.more())
    {
        sapItemsData = literator.value();

        select firstonly salesLine
        where salesLine.SalesId == salesTable.SalesId && salesLine.ItemId == sapItemsData;

        if (salesLine)
        {
            salesLine = SalesLine::find(salesId,salesLine.LineNum,true);
            literator.next();
            sapItemsData = literator.value();

            salesLine.SalesDeliverNow = str2Int(sapItemsData);
            salesLine.setInventDeliverNow();
            salesLine.doUpdate();                
        }
        literator.next();

    }

    salesFormLetter_PackingSlip = SalesFormLetter::construct(DocumentStatus::PackingSlip);
    // Post the invoice
    salesFormLetter_PackingSlip.update(salesTable, systemDateGet(), SalesUpdate::DeliverNow, AccountOrder::None, false, false); // Set to true to print the packingslip


    if (salesFormLetter_PackingSlip.parmJournalRecord().TableId == tableNum(custPackingSlipJour))
    {
        custPackingSlipJour = salesFormLetter_PackingSlip.parmJournalRecord();
        info(custPackingSlipJour.PackingSlipId);
    }
    ttsCommit;

    ttsbegin;
    salesFormLetter = SalesFormLetter::construct(DocumentStatus::Invoice);
    salesFormLetter.update(salesTable, systemDateGet(), SalesUpdate::PackingSlip);
    info(strFmt("sales: %1 invoiced",salesId));
    ttscommit;
}
